mapper.select:
SELECT r.id,r.restaurant_id,r.previous_request_id,r.request_type,r.status,r.created_at,r.reviewed_at,
    r.withdrawn_at,
    JSON_UNQUOTE(JSON_EXTRACT(r.proposed_data,'$.name')) AS request_name,
    (SELECT COUNT(*) FROM restaurant_change_photos p WHERE p.request_id=r.id) AS photo_count
FROM restaurant_change_requests r WHERE r.submitted_by=#{owner}
AND r.status=#{query.status}
ORDER BY r.created_at DESC,r.id DESC LIMIT #{query.pageSize} OFFSET #{offset}
